// Convites não alteram saldos. O vínculo e as comissões são validados no servidor.
export function normalizeReferral(value='') {
 const code=String(value).trim().toUpperCase();
 if(code&&!/^[A-Z0-9][A-Z0-9-]{2,23}$/.test(code))throw new Error('Use um código de indicação de 3 a 24 letras, números ou hífens.');
 return code;
}
export function referralFromUrl(value) {
 const url=new URL(value,'https://liferobots.invalid');
 const hashQuery=url.hash.includes('?')?url.hash.slice(url.hash.indexOf('?')+1):'';
 const code=url.searchParams.get('ref')??new URLSearchParams(hashQuery).get('ref')??'';
 return normalizeReferral(code);
}
export function referralLink(base,code) {
 const url=new URL(base);url.search='';url.hash='signup';
 url.searchParams.set('ref',normalizeReferral(code));return url.href;
}
export function acceptDemoReferral(state,value) {
 const code=normalizeReferral(value);
 if(code===state.profile.referralCode)throw new Error('Use o código de outro piloto para receber uma indicação.');
 if(state.profile.signupReferralSet&&code!==(state.profile.referredByCode||''))throw new Error('A indicação desta conta de teste já foi registrada.');
 state.profile.referredByCode=code||null;state.profile.signupReferralSet=true;return code;
}
export function teamSummary(state,level=0){
 const members=state.affiliates.filter(a=>!level||a.level===level);
 return {members:members.length,robots:members.reduce((n,a)=>n+Number(a.robots||0),0),daily:members.reduce((n,a)=>n+Number(a.daily||0),0),commission:members.reduce((n,a)=>n+Number(a.commission||0),0),estimated:members.reduce((n,a)=>n+Math.floor(Number(a.daily||0)*(state.settings.commissions[a.level-1]||0))/100,0)};
}
export function whatsappLink(value){const digits=String(value||'').replace(/[^0-9]/g,'');return /^\d{10,15}$/.test(digits)?'https://wa.me/'+(digits.length<=11?'55':'')+digits:null;}
export function createReferralView(env) {
 const {core:C,escape:esc,icon:I,coin,button:btn,format:n,approximateBRL:brl,sprite,assetUrl}=env;
 const equivalent=v=>brl(v/env.getState().settings.rcPerLC/env.getState().settings.lcPerReal);
 function render(){const s=env.getState(),code=s.profile.referralCode||'',link=code?referralLink(env.baseUrl(),code):'',demo=env.isDemo,summary=teamSummary(s),level=env.getLevel?.()||0,members=s.affiliates.filter(a=>!level||a.level===level);
  return `${env.heading('MINHA EQUIPE','Uma jornada que cresce junto.','Convide pilotos e acompanhe a produção da sua rede.')}<section class="referral-banner"><div class="referral-signal" aria-hidden="true"><img src="${assetUrl('map-beacon.png')}" alt=""></div><div class="referral-invitation"><span class="eyebrow">PORTAL DE CONVITES</span><h2>Traga sua equipe para Aurora.</h2><p>O convite abre o cadastro com seu código preenchido. Sua comissão acompanha os rendimentos creditados dos robôs indicados.</p><div class="referral-code"><span>SEU CÓDIGO</span><b>${esc(code||'Disponível após o cadastro')}</b>${code?btn(I('copy')+' Copiar código','copy-ref-code','','secondary'):''}</div><div class="invite-link"><input aria-label="Link de cadastro da sua equipe" readonly value="${esc(link)}"><button data-a="copy-ref" ${!link?'disabled':''} aria-label="Copiar link de cadastro">${I('copy')}</button></div><div class="referral-actions">${btn(I('users')+' Compartilhar convite','share-ref',!link?'disabled':'','primary')}${btn('Ver cadastro','preview-ref','','secondary')}</div>${s.profile.referredByCode?`<small>Sua indicação: ${esc(s.profile.referredByCode)}</small>`:''}</div><div class="referral-total">${coin('RC')}<small>COMISSÕES ${demo?'DE TESTE':'DA EQUIPE'}</small><b>${n(s.commissionTotal)} <span>RC</span></b><span>≈ ${equivalent(s.commissionTotal)}</span></div></section><div class="network-overview"><article>${I('users')}<b>${summary.members}</b><small>Pilotos na equipe</small></article><article>${I('robot')}<b>${summary.robots}</b><small>Robôs da rede</small></article><article>${coin('RC')}<b>${n(summary.daily)} RC</b><small>Produção da equipe / dia</small></article><article>${I('gift')}<b>${n(summary.estimated)} RC</b><small>Comissão estimada / dia</small></article></div><section class="network-tree"><div class="network-pilot"><img src="${assetUrl('nexa-guide.png')}" alt="Assistente da rede"><span>VOCÊ</span><b>${esc(s.profile.name)}</b></div><div class="network-branches">${s.settings.commissions.map((rate,i)=>{const tier=teamSummary(s,i+1);return `<button data-a="affiliate-tab" data-id="${i+1}" class="network-tier ${level===i+1?'selected':''}"><span class="tier-orbit">${I('users')}<i>${i+1}</i></span><span>NÍVEL ${i+1}</span><b>${rate}%</b><p>${['Convites diretos','Equipe dos seus convidados','Terceira geração'][i]}</p><small>${tier.members} pilotos · ${n(tier.daily)} RC / dia</small><strong>${n(tier.estimated)} RC / dia estimados</strong></button>`;}).join('')}</div></section><div class="notice">${I('info')} ${demo?'Os pilotos exibidos são exemplos e as comissões são fictícias.':'O servidor confirma o vínculo e paga as comissões diariamente sobre a produção efetiva.'} A devolução do valor de aquisição não gera comissão.</div><div class="section-title"><h2>Pilotos da sua equipe</h2><span>${members.length} no filtro</span></div><div class="tabs network-filters">${[0,1,2,3].map(i=>`<button data-a="affiliate-tab" data-id="${i}" class="${level===i?'active':''}">${i?'Nível '+i:'Toda a equipe'} <small>${teamSummary(s,i).members}</small></button>`).join('')}</div><div class="affiliate-roster">${members.map((a,i)=>{const model=s.catalog.find(r=>r.id===a.robotId)||s.catalog[i%s.catalog.length],phone=whatsappLink(a.whatsapp);return `<article><div class="affiliate-portrait">${sprite(model)}<span>NV. ${a.level}</span></div><div class="affiliate-identity"><span class="eyebrow">NÍVEL ${a.level}</span><h3>${esc(a.name)}</h3><small>${n(a.robots)} robôs · ${n(a.daily)} RC / dia</small><span class="affiliate-phone">${I('users')} ${esc(a.whatsapp||'WhatsApp não cadastrado')}</span></div><div class="affiliate-commission"><small>Comissão acumulada</small><b>${coin('RC')}${n(a.commission)} RC</b><span>≈ ${equivalent(a.commission)}</span></div><div class="affiliate-actions">${btn('Ver piloto '+I('arrow'),'affiliate-detail',`data-id="${esc(a.id)}"`,'secondary')}${phone?`<a class="text-btn" target="_blank" rel="noopener noreferrer" href="${phone}">WhatsApp ${I('arrow')}</a>`:''}</div></article>`;}).join('')||'<div class="empty">Nenhum piloto neste nível. Sua equipe começa com o primeiro convite.</div>'}</div>`;
 }
 function open(id){const s=env.getState(),a=s.affiliates.find(x=>x.id===id);if(!a)return;const model=s.catalog.find(r=>r.id===a.robotId)||s.catalog[0],phone=whatsappLink(a.whatsapp),b=a.battles||{},items=a.acquisitions||[],missing='—';
  env.modal(`<div class="affiliate-profile-hero">${sprite(model)}<span class="eyebrow">PILOTO DA EQUIPE · NÍVEL ${a.level}</span><h2 id="modal-title">${esc(a.name)}</h2><p>${env.isDemo?'Perfil de exemplo da demonstração':'Informações da sua rede de indicação'}</p></div><div class="affiliate-contact"><span>WhatsApp</span><b>${esc(a.whatsapp||'Não cadastrado')}</b>${phone?`<a class="btn secondary" target="_blank" rel="noopener noreferrer" href="${phone}">Abrir WhatsApp ${I('arrow')}</a>`:''}</div><div class="detail-grid"><div><small>Robôs adquiridos</small><b>${n(a.acquisitionCount??a.robots)}</b></div><div><small>Produção / dia</small><b>${n(a.daily)} RC</b></div><div><small>Batalhas</small><b>${b.played??missing}</b></div><div><small>Vitórias / derrotas</small><b>${b.wins!=null?b.wins+' / '+b.losses:missing}</b></div><div><small>Comissão que você recebeu</small><b>${n(a.commission)} RC</b></div><div><small>Taxa deste nível</small><b>${s.settings.commissions[a.level-1]}%</b></div></div><div class="section-title"><h3>Robôs e aquisições do piloto</h3></div><div class="affiliate-acquisitions">${items.map(item=>{const r=s.catalog.find(x=>x.id===item.catalogId)||model;return `<article>${sprite(r)}<div><b>${esc(r.name)}</b><small>${item.active===false?'Prazo encerrado':'Em atividade'} · NV. ${item.level||1}</small><span>${item.paidAmount!=null?n(item.paidAmount)+' '+esc(item.currency||'LC'):'Valor de aquisição não informado'}</span></div></article>`;}).join('')||'<p class="subtle">Os detalhes de aquisição serão exibidos quando forem informados pelo servidor.</p>'}</div>${btn('Voltar à equipe','close','','primary wide')}`,'affiliate-profile-modal');
 }
 return {render,open,link:()=>referralLink(env.baseUrl(),env.getState().profile.referralCode)};
}
